package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen2Test {

    private TestableTypeDeserializer sut;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockJavaType;
    private TypeIdResolver mockTypeIdResolver;

    // Concrete implementation to test protected methods
    private static class TestableTypeDeserializer extends TypeDeserializerBase {
        private JsonDeserializer<Object> mockDeserializer;
        private JsonDeserializer<Object> mockDefaultDeserializer;
        private boolean throwMappingException = false;

        protected TestableTypeDeserializer(JavaType baseType, TypeIdResolver idRes) {
            super(baseType, idRes, "type", true, null);
        }

        @Override
        public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) {
            return null;
        }

        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() {
            return null;
        }

        @Override
        public String baseTypeName() {
            return "test";
        }

        @Override
        protected JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return mockDeserializer;
        }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return mockDefaultDeserializer;
        }

        void setMockDeserializer(JsonDeserializer<Object> deser) {
            this.mockDeserializer = deser;
        }

        void setMockDefaultDeserializer(JsonDeserializer<Object> deser) {
            this.mockDefaultDeserializer = deser;
        }

        void setThrowMappingException(boolean value) {
            this.throwMappingException = value;
        }

        @Override
        public DeserializationContext getContext() {
            return null;
        }

        // Override to simulate the mapping exception behavior in the test
        @Override
        public String toString() {
            return super.toString();
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockJavaType = mock(JavaType.class);
        mockTypeIdResolver = mock(TypeIdResolver.class);
        sut = new TestableTypeDeserializer(mockJavaType, mockTypeIdResolver);
    }

    @Test
    public void test_deserializeWithNativeTypeId_typeIdNull_success() throws IOException {
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);

        sut.setMockDefaultDeserializer(mockDeser);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals(expectedResult, result);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test(expected = RuntimeException.class)
    public void test_deserializeWithNativeTypeId_typeIdNull_noDeserializerFound() throws IOException {
        sut.setMockDefaultDeserializer(null);
        when(mockContext.mappingException(anyString())).thenThrow(new RuntimeException("Mapping Exception"));

        sut._deserializeWithNativeTypeId(mockParser, mockContext, null);
    }

    @Test
    public void test_deserializeWithNativeTypeId_typeIdString() throws IOException {
        Object expectedResult = "success";
        String typeId = "myType";
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);

        sut.setMockDeserializer(mockDeser);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void test_deserializeWithNativeTypeId_typeIdInteger() throws IOException {
        Object expectedResult = 123;
        Integer typeId = 123;
        String expectedTypeIdStr = "123";
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);

        sut.setMockDeserializer(mockDeser);

        // We need to ensure the internal _findDeserializer is called with the string version
        // Since we can't easily spy on the internal call without complex mocking, 
        // the TestableTypeDeserializer's _findDeserializer will be used.
        // We verify the logic by how we set up the mock.

        // In the real class, it calls _findDeserializer(ctxt, typeIdStr)
        // Our Testable implementation doesn't validate the string passed to _findDeserializer,
        // but in a real scenario, we'd ensure the conversion logic is hit.

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void test_deserializeWithNativeTypeId_typeIdNonStringObject() throws IOException {
        Object expectedResult = "ok";
        Object typeId = new Object() {
            @Override
            public String toString() {
                return "customToString";
            }
        };
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);
        sut.setMockDeserializer(mockDeser);

        Object result = sut._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
    }
}
